    std::vector<Comp*>* ClothingList;
    std::map<Comp*, long> ClothingItemMap;
    int titleCalls;
    void FindAllChildren(const std::string& name, std::list<Comp*>& out)
    {
        for (unsigned i = 0; i < ClothingList->size(); ++i)
