            entry->AddActionOnBack(reset);
            list->AddScrollingChildAndSetOffsets(entry);
            if (worn)
                entry->MakeUnavailable();
            else
                entry->AddChild(actions);
            AddClothingMenuEntry(part, entry.Get());
        }
        return list;
    }
