template <class _Tp, class _Alloc>
std::_List_base<_Tp, _Alloc>::_List_base(const _Alloc&) : _M_node(allocator<_List_node<_Tp> >(), 0)
{
    _List_node<_Tp>* n = _M_node.allocate(1);
    n->_M_next = n;
    n->_M_prev = n;
    _M_node._M_data = n;
}
